import{_ as i,o as l,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Performance meeting 2019-01-17","description":"","frontmatter":{"title":"Ceph Performance meeting 2019-01-17","date":"2019-01-17T00:00:00.000Z","updated":"2019-02-03T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH algorithm","高可用性","可扩展性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","BlueStore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","消息编码","复制","快照","克隆","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","磁盘","SSD","HDD","JBOD","SAN","NAS","网络","网络拓扑","失败域","恢复","弹性","负载均衡","缓存","压缩","去重","质量分级","性能调整","基准测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Ceph_Performance_meeting_2019-01-17.md","filePath":"posts/2019/Ceph_Performance_meeting_2019-01-17.md","lastUpdated":1780460162000}'),r={name:"posts/2019/Ceph_Performance_meeting_2019-01-17.md"};function n(o,e,s,p,u,d){return l(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年1月17日</p><p><strong>参会人员</strong>： Casey, Mark, Sage, John, Keith, Haeju, Jason, Peter, Orlando, Radek, Linda, Adrian</p><p><strong>会议主题</strong>： Ceph 项目进展、问题讨论及后续行动计划</p><p><strong>关键细节</strong>：</p><ul><li><strong>Ceph 项目进展</strong>： <ul><li>Mark 提到在 Minneapolis F Meetup 上了解到 RGW 多站点存在分布式复制问题，数据未能正确复制，可能是静默失败。</li><li>Sage 提到最近进行了核心会议，讨论了异步和 RGW 的工作，希望 Nautilus 版本能成为默认选项。</li><li>Haeju 开发了一个新命令，可以轻松显示每个 OSD 的存储和网络 Numa 节点，并可以轻松固定。</li><li>Jason 正在重新审查代码，以优化缓存和线程。</li><li>Sage 提到已将 Cass 开源，并可以将其用于 Ceph。</li><li>Adrian 提到正在尝试重新编写 Blue Store，以支持更多存储设备。</li></ul></li><li><strong>问题讨论</strong>： <ul><li>Mark 询问 Sage 是否已合并新的 Numa 节点命令。</li><li>Sage 回答已合并，并提到该命令可以帮助优化参考架构。</li><li>Radek 提到正在尝试获取 Bdev 驱动程序，以支持 NVMe。</li><li>Orlando 提到正在尝试获取 Quanta 系统的报价，以获取平衡的 NVMe 系统。</li><li>Linda 提到正在尝试解决网络配置问题，以确保数据包正确路由。</li><li>Adrian 提到正在尝试获取 Quanta 系统的报价，以获取平衡的 NVMe 系统。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>Sage 将继续关注 RGW 多站点问题。</li><li>Haeju 将继续优化缓存和线程。</li><li>Jason 将继续审查代码。</li><li>Sage 将尝试将 Cass 开源。</li><li>Adrian 将尝试重新编写 Blue Store。</li><li>Orlando 将尝试获取 Quanta 系统的报价。</li><li>Linda 将尝试解决网络配置问题。</li></ul></li></ul><p><strong>计算机科学/ceph相关领域英文原文关键词</strong>：</p><ul><li>RGW multi-site</li><li>distributed replication</li><li>OMAP</li><li>asynchrony</li><li>rgw</li><li>Nautilus</li><li>OSD</li><li>Numa</li><li>NVMe</li><li>Bdev</li><li>Cass</li><li>reference architecture</li><li>network configuration</li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了 Ceph 项目的最新进展、存在的问题以及后续行动计划。参会人员就 RGW 多站点问题、异步和 RGW 的工作、Blue Store 优化等问题进行了深入讨论，并制定了相应的解决方案。会议特别强调了 Numa 节点优化、NVMe 支持和网络配置问题的重要性。</p>',10)])])}const c=i(r,[["render",n]]);export{_ as __pageData,c as default};
